// Some portions generated by Codex
const fs = require('node:fs');
const path = require('node:path');
const { spawn } = require('node:child_process');

const children = new Set();
let interrupted = 0;
for (const [signal, status] of [['SIGINT', 130], ['SIGTERM', 143]]) {
    process.once(signal, () => {
        interrupted = status;
        for (const child of children) {
            try {
                // Each command owns a process group, including its X server and browser descendants.
                process.kill(process.platform === 'win32' ? child.pid : -child.pid, signal);
            } catch (error) {
                if (error.code !== 'ESRCH') throw error;
            }
        }
    });
}

function run(args, env = process.env, display = false) {
    if (interrupted) return Promise.resolve(interrupted);
    const command = display ? 'xvfb-run' : 'npx';
    const commandArgs = display ? ['-a', '-s', '-screen 0 1280x1024x24 -nolisten tcp', 'npx', ...args] : args;
    return new Promise(resolve => {
        const child = spawn(command, commandArgs, {
            env, stdio: 'inherit', detached: process.platform !== 'win32'
        });
        children.add(child);
        child.once('error', error => {
            children.delete(child);
            console.error(`Unable to start ${command}: ${error.message}`);
            resolve(1);
        });
        child.once('exit', code => {
            children.delete(child);
            resolve(code ?? 1);
        });
    });
}

async function main() {
    const shardCount = Number(process.env.E2E_SHARDS ?? 1);
    if (!Number.isSafeInteger(shardCount) || shardCount < 1) {
        throw new Error('E2E_SHARDS must be a positive integer');
    }
    const args = ['playwright', 'test'];
    if (process.env.E2E_BROWSER) args.push(`--project=${process.env.E2E_BROWSER}`);
    args.push(...process.argv.slice(2));
    const display = process.env.E2E_NEEDS_XVFB === 'true';
    // Preserve explicit focused filters instead of replacing them with the phase's grep options.
    const focused = args.some(arg => /^--grep(?:-invert)?(?:=|$)/.test(arg) || /^-[gG]/.test(arg));
    if (shardCount === 1 || focused) return run(args, process.env, display);

    // Shards keep an entire spec on one worker. Each headed browser gets its own display so focus,
    // native scrolling and clipboard assertions cannot interfere with a concurrently running spec.
    fs.mkdirSync('blob-report', { recursive: true });
    const reports = fs.mkdtempSync(path.resolve('blob-report', 'shards-'));
    const outcomes = await Promise.all(Array.from({ length: shardCount }, (_, index) => {
        const shard = index + 1;
        return run([...args, `--shard=${shard}/${shardCount}`, '--grep-invert=@performance',
            '--pass-with-no-tests', '--workers=1', '--reporter=line,blob',
            `--output=test-results/shard-${shard}`],
        { ...process.env, PLAYWRIGHT_BLOB_OUTPUT_FILE: path.join(reports, `report-${shard}.zip`) }, display);
    }));
    if (interrupted) return interrupted;
    // Wall-clock performance gates need the runner's CPU to themselves. Keep their existing budgets and
    // execute them after both functional shards, with their results included in the same combined report.
    outcomes.push(await run([...args, '--grep=@performance', '--pass-with-no-tests', '--workers=1',
        '--reporter=line,blob', '--output=test-results/performance'],
    { ...process.env, PLAYWRIGHT_BLOB_OUTPUT_FILE: path.join(reports, 'report-performance.zip') }, display));
    if (interrupted) return interrupted;
    // Keep the other shard running after a failure and merge its diagnostics as well. A failed test or
    // failed merge must still fail CI; the HTML report and raw blobs remain available for inspection.
    const summary = path.join(reports, 'merged.json');
    const merged = await run(['playwright', 'merge-reports', '--reporter=html,json', reports],
        { ...process.env, PLAYWRIGHT_HTML_OPEN: 'never', PLAYWRIGHT_JSON_OUTPUT_FILE: summary });
    const failed = outcomes.find(status => status !== 0) || merged;
    if (failed) return failed;
    // A focused selection can leave an individual phase empty. The entire selection must still contain tests.
    const { stats } = JSON.parse(fs.readFileSync(summary, 'utf8'));
    if (!stats || !(stats.expected + stats.unexpected + stats.flaky + stats.skipped > 0)) {
        throw new Error('No tests found in the selected E2E suite');
    }
    return 0;
}

main().then(status => { process.exitCode = interrupted || status; }).catch(error => {
    console.error(error);
    process.exitCode = interrupted || 1;
});
